package com.test;

public class Exp5 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("Even numbers from 1 to 10 : ");
		for (int i = 0; i <=10; i+=2)
		{
			System.out.println(i);
		}
		
		int y = 1;
		while (y <= 10) {
			System.out.println(y);
			y += 2;
		}
	}

}
